  @@unique([access_token])
  @@unique([refresh_token])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, created_at], map: "shopping_mall_seller_sessions_shopping_mall_seller_id__0b9ab7e6")
  @@index([expired_at])
}

/// Password reset tokens for seller accounts enabling email-based password
