import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test admin session continuity and profile preservation during token refresh.
 *
 * This test validates that:
 * 1. Admin profile data remains consistent across refresh operations
 * 2. New token pairs are issued on each refresh
 * 3. Token timestamps are valid and properly set
 * 4. Multiple sequential refreshes maintain session integrity
 */
export async function test_api_admin_auth_refresh_session_continuity(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create admin account with specific profile data
  const adminConnection: api.IConnection = { host: connection.host };
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminName = RandomGenerator.name();
  const joinResult = await authorize_admin_join(adminConnection, {
    body: {
      email: adminEmail,
      password: RandomGenerator.alphaNumeric(16),
      name: adminName,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(joinResult);
  // Capture initial profile data
  const initialId = joinResult.id;
  const initialEmail = joinResult.email;
  const initialGrade = joinResult.grade;
  const initialName = joinResult.name;
  const initialCreatedAt = joinResult.created_at;
  // Validate initial profile data
  TestValidator.equals("initial email matches", initialEmail, adminEmail);
  TestValidator.equals("initial name matches", initialName, adminName);
  TestValidator.equals("initial grade is regular", initialGrade, "regular");
  TestValidator.predicate(
    "initial deleted_at is null",
    joinResult.deleted_at === null,
  );
  // Validate initial token structure
  TestValidator.predicate(
    "initial access token exists",
    joinResult.access.length > 0,
  );
  TestValidator.predicate(
    "initial refresh token exists",
    joinResult.refresh.length > 0,
  );
  TestValidator.predicate(
    "initial token.access exists",
    joinResult.token.access.length > 0,
  );
  TestValidator.predicate(
    "initial token.refresh exists",
    joinResult.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "initial expired_at is future",
    new Date(joinResult.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "initial token.expired_at is future",
    new Date(joinResult.token.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "initial refreshable_until is future",
    new Date(joinResult.token.refreshable_until) > new Date(),
  );
  // Store refresh tokens from each refresh for validation
  const refreshResults: IShoppingMallAdmin.IAuthorized[] = [];
  let currentRefreshToken = joinResult.refresh;
  // Step 2: Perform multiple sequential refreshes (5 times)
  const refreshCount = 5;
  for (let i = 0; i < refreshCount; i++) {
    const refreshConnection: api.IConnection = { host: connection.host };
    const refreshResult = await authorize_admin_refresh(refreshConnection, {
      body: {
        refresh_token: currentRefreshToken,
      } satisfies IShoppingMallAdmin.IRefresh,
    });
    typia.assert(refreshResult);
    refreshResults.push(refreshResult);
    // Update current refresh token for next iteration
    currentRefreshToken = refreshResult.refresh;
    // Step 3: Validate profile data remains consistent
    TestValidator.equals(
      `refresh ${i + 1}: id unchanged`,
      refreshResult.id,
      initialId,
    );
    TestValidator.equals(
      `refresh ${i + 1}: email unchanged`,
      refreshResult.email,
      initialEmail,
    );
    TestValidator.equals(
      `refresh ${i + 1}: grade unchanged`,
      refreshResult.grade,
      initialGrade,
    );
    TestValidator.equals(
      `refresh ${i + 1}: name unchanged`,
      refreshResult.name,
      initialName,
    );
    TestValidator.equals(
      `refresh ${i + 1}: created_at unchanged`,
      refreshResult.created_at,
      initialCreatedAt,
    );
    TestValidator.predicate(
      `refresh ${i + 1}: deleted_at is null`,
      refreshResult.deleted_at === null,
    );
    // Step 4: Validate token structure
    TestValidator.predicate(
      `refresh ${i + 1}: access token exists`,
      refreshResult.access.length > 0,
    );
    TestValidator.predicate(
      `refresh ${i + 1}: refresh token exists`,
      refreshResult.refresh.length > 0,
    );
    TestValidator.predicate(
      `refresh ${i + 1}: token.access exists`,
      refreshResult.token.access.length > 0,
    );
    TestValidator.predicate(
      `refresh ${i + 1}: token.refresh exists`,
      refreshResult.token.refresh.length > 0,
    );
    // Validate token timestamps are in the future
    TestValidator.predicate(
      `refresh ${i + 1}: expired_at is future`,
      new Date(refreshResult.expired_at) > new Date(),
    );
    TestValidator.predicate(
      `refresh ${i + 1}: token.expired_at is future`,
      new Date(refreshResult.token.expired_at) > new Date(),
    );
    TestValidator.predicate(
      `refresh ${i + 1}: refreshable_until is future`,
      new Date(refreshResult.token.refreshable_until) > new Date(),
    );
    // Validate access token expiry is within expected range (15-30 minutes from now)
    const expiredAtTime = new Date(refreshResult.expired_at).getTime();
    const now = Date.now();
    const minutesUntilExpiry = (expiredAtTime - now) / (1000 * 60);
    TestValidator.predicate(
      `refresh ${i + 1}: access expires in reasonable time`,
      minutesUntilExpiry > 10 && minutesUntilExpiry < 60,
    );
    // Validate refreshable_until is after expired_at (session duration longer than access token life)
    TestValidator.predicate(
      `refresh ${i + 1}: refreshable_until after expired_at`,
      new Date(refreshResult.token.refreshable_until) >
        new Date(refreshResult.expired_at),
    );
  }
  // Step 5: Verify tokens change between refreshes
  for (let i = 0; i < refreshResults.length - 1; i++) {
    TestValidator.notEquals(
      `access tokens differ between refresh ${i + 1} and ${i + 2}`,
      refreshResults[i].access,
      refreshResults[i + 1].access,
    );
    TestValidator.notEquals(
      `refresh tokens differ between refresh ${i + 1} and ${i + 2}`,
      refreshResults[i].refresh,
      refreshResults[i + 1].refresh,
    );
  }
  // Step 6: Verify all profile data across all refreshes is identical
  for (let i = 0; i < refreshResults.length; i++) {
    TestValidator.equals(
      `all refreshes: id consistent ${i + 1}`,
      refreshResults[i].id,
      initialId,
    );
    TestValidator.equals(
      `all refreshes: email consistent ${i + 1}`,
      refreshResults[i].email,
      initialEmail,
    );
    TestValidator.equals(
      `all refreshes: grade consistent ${i + 1}`,
      refreshResults[i].grade,
      initialGrade,
    );
    TestValidator.equals(
      `all refreshes: name consistent ${i + 1}`,
      refreshResults[i].name,
      initialName,
    );
    TestValidator.equals(
      `all refreshes: created_at consistent ${i + 1}`,
      refreshResults[i].created_at,
      initialCreatedAt,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCustomer";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test administrative customer list retrieval with comprehensive search filters.
 *
 * This test validates the customer search API functionality including:
 * - Pagination with correct metadata
 * - Multiple filter combinations
 * - Sorting options
 * - Response structure validation
 */
export async function test_api_customer_list_search_with_pagination(
  connection: api.IConnection,
): Promise<void> {
  // Test 1: Basic pagination with default sorting (newest first)
  const firstPage = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        sort: "created_at_desc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(firstPage);
  // Validate pagination metadata
  TestValidator.equals(
    "pagination current page should be 1",
    firstPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 10",
    firstPage.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "pagination records should be non-negative",
    firstPage.pagination.records >= 0,
  );
  TestValidator.equals(
    "pagination pages should be calculated correctly",
    firstPage.pagination.pages,
    Math.ceil(firstPage.pagination.records / firstPage.pagination.limit),
  );
  // Validate data array structure
  TestValidator.predicate(
    "data array should not exceed limit",
    firstPage.data.length <= firstPage.pagination.limit,
  );
  // Validate each customer summary
  for (const customer of firstPage.data) {
    typia.assert(customer);
    // Customer fields validated by typia.assert, only business logic checks below
  }
  // Test 2: Sorting by email ascending
  const sortedByEmail = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        sort: "email_asc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(sortedByEmail);
  // Validate email ascending sort order
  for (let i = 1; i < sortedByEmail.data.length; i++) {
    const prev = sortedByEmail.data[i - 1];
    const curr = sortedByEmail.data[i];
    TestValidator.predicate(
      "emails should be sorted ascending",
      prev.email.localeCompare(curr.email) <= 0,
    );
  }
  // Test 3: Sorting by created_at ascending (oldest first)
  const sortedByOldest = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        sort: "created_at_asc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(sortedByOldest);
  // Validate date ascending sort order
  for (let i = 1; i < sortedByOldest.data.length; i++) {
    const prev = sortedByOldest.data[i - 1];
    const curr = sortedByOldest.data[i];
    TestValidator.predicate(
      "created_at should be sorted ascending",
      new Date(prev.createdAt).getTime() <= new Date(curr.createdAt).getTime(),
    );
  }
  // Test 4: Filter by isDeleted status (active accounts only)
  const activeCustomers = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        isDeleted: false,
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(activeCustomers);
  // Validate all returned customers are active (not deleted)
  for (const customer of activeCustomers.data) {
    TestValidator.equals(
      "active filter should only return non-deleted customers",
      customer.isDeleted,
      false,
    );
  }
  // Test 5: Filter by isDeleted status (deleted accounts only)
  const deletedCustomers = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        isDeleted: true,
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(deletedCustomers);
  // Validate all returned customers are deleted
  for (const customer of deletedCustomers.data) {
    TestValidator.equals(
      "deleted filter should only return deleted customers",
      customer.isDeleted,
      true,
    );
  }
  // Test 6: Pagination - second page
  if (firstPage.pagination.pages > 1) {
    const secondPage = await api.functional.shoppingMall.customers.index(
      connection,
      {
        body: {
          page: 2,
          limit: 10,
        } satisfies IShoppingMallCustomer.IRequest,
      },
    );
    typia.assert(secondPage);
    TestValidator.equals(
      "second page current should be 2",
      secondPage.pagination.current,
      2,
    );
    TestValidator.equals(
      "second page limit should match first page",
      secondPage.pagination.limit,
      firstPage.pagination.limit,
    );
    TestValidator.equals(
      "total records should be consistent across pages",
      secondPage.pagination.records,
      firstPage.pagination.records,
    );
    // Validate no duplicate customers between pages
    const firstPageIds = new Set(firstPage.data.map((c) => c.id));
    for (const customer of secondPage.data) {
      TestValidator.predicate(
        "customer should not appear in multiple pages",
        !firstPageIds.has(customer.id),
      );
    }
  }
  // Test 7: Date range filtering
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const recentCustomers = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        createdFrom: thirtyDaysAgo.toISOString(),
        createdTo: now.toISOString(),
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(recentCustomers);
  // Validate all returned customers are within date range
  for (const customer of recentCustomers.data) {
    const createdDate = new Date(customer.createdAt);
    TestValidator.predicate(
      "customer created_at should be within date range",
      createdDate >= thirtyDaysAgo && createdDate <= now,
    );
  }
  // Test 8: Empty filter criteria returns all customers
  const allCustomers = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 50,
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(allCustomers);
  TestValidator.predicate(
    "empty filter should return customers",
    allCustomers.pagination.records >= 0,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCustomer";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

export async function test_api_customer_list_filter_by_deleted_status(
  connection: api.IConnection,
): Promise<void> {
  // Test filtering customers by account deletion status
  // 1. Filter by isDeleted: true to get only soft-deleted accounts
  // 2. Filter by isDeleted: false to get only active accounts
  // 3. Filter without isDeleted to get all accounts
  // Step 1: Get only deleted accounts
  const deletedOnly = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: { isDeleted: true } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(deletedOnly);
  // All returned customers should have isDeleted: true
  TestValidator.predicate(
    "all customers should be deleted when isDeleted: true",
    deletedOnly.data.every((customer) => customer.isDeleted === true),
  );
  // Step 2: Get only active accounts
  const activeOnly = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: { isDeleted: false } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(activeOnly);
  // All returned customers should have isDeleted: false
  TestValidator.predicate(
    "all customers should be active when isDeleted: false",
    activeOnly.data.every((customer) => customer.isDeleted === false),
  );
  // Step 3: Get all accounts (both active and deleted)
  const allCustomers = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {} satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(allCustomers);
  // Total should equal sum of deleted and active counts
  TestValidator.equals(
    "total count should equal deleted + active counts",
    allCustomers.pagination.records,
    deletedOnly.pagination.records + activeOnly.pagination.records,
  );
  // Step 4: Verify deleted accounts have preserved profile information
  if (deletedOnly.data.length > 0) {
    const deletedCustomer = deletedOnly.data[0];
    typia.assert(deletedCustomer);
    TestValidator.predicate(
      "deleted customer has valid id",
      deletedCustomer.id !== null && deletedCustomer.id !== undefined,
    );
    TestValidator.predicate(
      "deleted customer has valid email",
      deletedCustomer.email !== null && deletedCustomer.email !== undefined,
    );
    TestValidator.predicate(
      "deleted customer has valid createdAt",
      deletedCustomer.createdAt !== null &&
        deletedCustomer.createdAt !== undefined,
    );
  }
  // Step 5: Test with pagination for large datasets
  const pagedDeleted = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        isDeleted: true,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(pagedDeleted);
  TestValidator.predicate(
    "paged results respect limit",
    pagedDeleted.data.length <= 10,
  );
  TestValidator.equals(
    "pagination current page is 1",
    pagedDeleted.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination limit matches request",
    pagedDeleted.pagination.limit <= 10,
  );
  // Step 6: Verify sorting is maintained within filtered results
  const sortedDeleted = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        isDeleted: true,
        sort: "created_at_desc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(sortedDeleted);
  // Verify descending order by creation date (if more than one item)
  if (sortedDeleted.data.length > 1) {
    for (let i = 1; i < sortedDeleted.data.length; i++) {
      const prevDate = new Date(sortedDeleted.data[i - 1].createdAt).getTime();
      const currDate = new Date(sortedDeleted.data[i].createdAt).getTime();
      TestValidator.predicate(
        "sorted results maintain created_at_desc order",
        prevDate >= currDate,
      );
    }
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCustomer";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test customer list sorting by email address and registration date.
 *
 * **Scenario Flow:**
 * 1. Call PATCH /shoppingMall/customers with sort: email_asc to retrieve customers sorted alphabetically by email
 * 2. Call PATCH /shoppingMall/customers with sort: email_desc to retrieve customers sorted reverse-alphabetically by email
 * 3. Call PATCH /shoppingMall/customers with sort: created_at_asc to retrieve oldest customers first
 * 4. Call PATCH /shoppingMall/customers with sort: created_at_desc (default) to retrieve newest customers first
 * 5. Call PATCH /shoppingMall/customers without sort parameter to verify default behavior
 *
 * **Validations:**
 * - email_asc returns customers in ascending alphabetical order by email
 * - email_desc returns customers in descending alphabetical order by email
 * - created_at_asc returns customers with oldest registration first
 * - created_at_desc returns customers with newest registration first
 * - Default sort (no sort parameter) is created_at_desc (newest first)
 */
export async function test_api_customer_list_sort_order(
  connection: api.IConnection,
): Promise<void> {
  // Test email ascending sort
  const emailAsc = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        sort: "email_asc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(emailAsc);
  // Verify email ascending order
  for (let i = 1; i < emailAsc.data.length; i++) {
    TestValidator.predicate(
      "email_asc order",
      emailAsc.data[i - 1].email.localeCompare(emailAsc.data[i].email) <= 0,
    );
  }
  // Test email descending sort
  const emailDesc = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        sort: "email_desc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(emailDesc);
  // Verify email descending order
  for (let i = 1; i < emailDesc.data.length; i++) {
    TestValidator.predicate(
      "email_desc order",
      emailDesc.data[i - 1].email.localeCompare(emailDesc.data[i].email) >= 0,
    );
  }
  // Test created_at ascending sort
  const createdAsc = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        sort: "created_at_asc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(createdAsc);
  // Verify created_at ascending order (oldest first)
  for (let i = 1; i < createdAsc.data.length; i++) {
    TestValidator.predicate(
      "created_at_asc order",
      createdAsc.data[i - 1].createdAt <= createdAsc.data[i].createdAt,
    );
  }
  // Test created_at descending sort
  const createdDesc = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {
        sort: "created_at_desc",
      } satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(createdDesc);
  // Verify created_at descending order (newest first)
  for (let i = 1; i < createdDesc.data.length; i++) {
    TestValidator.predicate(
      "created_at_desc order",
      createdDesc.data[i - 1].createdAt >= createdDesc.data[i].createdAt,
    );
  }
  // Test default sort (no sort parameter) - should be created_at_desc
  const defaultSort = await api.functional.shoppingMall.customers.index(
    connection,
    {
      body: {} satisfies IShoppingMallCustomer.IRequest,
    },
  );
  typia.assert(defaultSort);
  // Verify default is created_at_desc order (newest first)
  for (let i = 1; i < defaultSort.data.length; i++) {
    TestValidator.predicate(
      "default sort is created_at_desc",
      defaultSort.data[i - 1].createdAt >= defaultSort.data[i].createdAt,
    );
  }
  // Verify total record count is consistent across different sort options
  TestValidator.equals(
    "total record count consistent across sorts",
    emailAsc.pagination.records,
    emailDesc.pagination.records,
  );
  TestValidator.equals(
    "total record count consistent across sorts",
    emailAsc.pagination.records,
    createdAsc.pagination.records,
  );
  TestValidator.equals(
    "total record count consistent across sorts",
    emailAsc.pagination.records,
    createdDesc.pagination.records,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

/**
 * Test retrieving an active customer profile by ID.
 *
 * This test validates:
 * 1. Customer profile retrieval returns all expected fields
 * 2. Email matches the registered email
 * 3. deletedAt is null for active accounts
 * 4. Customer ID matches the requested path parameter
 */
export async function test_api_customer_profile_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create a test customer using utility function
  const customerConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_customer_join(customerConnection, {});
  typia.assert(authorized);
