    customerConnection,
    {},
  );
  typia.assert(order);
  // 3. Find an order item with 'paid' status
  const paidOrderItem = order.orderItems.find((item) => item.status === "paid");
  if (!paidOrderItem) {
    throw new Error("No order item with 'paid' status found");
