    "unauthorized customer cannot delete another's review",
    403,
    async () =>
      await api.functional.shoppingMall.customer.reviews.erase(
        customer2Connection,
        { reviewId: review.id },
      ),
  );
  // 7. Cleanup: Delete the review as the rightful owner
  await api.functional.shoppingMall.customer.reviews.erase(
    customer1Connection,
    {
      reviewId: review.id,
    },
  );
}

