      {
        orderId: order.id,
        body: {
          reason: forceCancelReason,
        } satisfies IShoppingMallOrder.IForceCancel,
      },
    );
  typia.assert(cancelledOrder);
  // 10. Validations
  // Verify order status changed to 'cancelled'
  TestValidator.equals(
