  TestValidator.predicate(
    "Seller 2 variant has stock",
    variant2.options.length > 0,
  );
  // The force-cancel operation requires:
  // 1. Valid order ID (string & Format<"uuid">)
  // 2. Reason (string & MinLength<1>)
  // 3. Admin authentication
