  // Verify both sellers are approved
  TestValidator.equals(
    "Seller 1 is approved",
    seller1Auth.approvalStatus,
    "approved",
  );
  TestValidator.equals(
    "Seller 2 is approved",
    seller2Auth.approvalStatus,
