      0,
    );
    return {
      id: input.id,
      sku_code: input.sku_code,
      price: input.price,
      options: await ArrayUtil.asyncMap(
        input.options,
        ShoppingMallProductVariantAtOptionTransformer.transform,
      ),
      stock_quantity: stock_quantity,
      in_stock: stock_quantity > 0,
    };
  }
}

